class env_setup:
    """
    This is a library to set up test environment. It allows user to configure BTS (eNB, gNB, Cloud BTS a.k.a. VRAN),
    simulators (IPhy, RTG, CUS, AirPhone) and Core Networks (EPC, 5GC).
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    _CONFIGURE_CALLED = False
    _CONFIGURE_CALL_COUNTER = count(1)

    def __init__(self) -> None:
        """Initialization method"""
        self._config: dict = {}
        self._call_counter: int = 1
        self._result_file = Path(TMP_DIR, RESULT_FILE)
        self._config_file = Path(TMP_DIR, CONFIG_FILE)
        atexit.register(kill_configuration_process)

    @cached_property
    def _output_dir(self) -> Path:
        return self._get_output_dir()

    def add_cloud_bts_configuration(
        self,
        vcu_scfc: str | list[str] | None = None,
        vdu_scfc: str | list[str] | None = None,
        host_id: str = "1",
        bts_recovery: bool = True,
        recovery_snapshot: bool = False,
    ):
        """
        Add Cloud BTS to the configuration, so it can be configured with proper files.
        You can configure only vCUs or vDUs or both. Keep in mind that position on the SCFC list will be the same
        as position in __init__.py file with TL declaration.

        :param str | list[str] | None vcu_scfc: List of names of SCFC for vCUs of the cloud BTS.
               Can be list of comma separated string.
        :param str | list[str] | None vdu_scfc: List of names of SCFC for vDUs of the cloud BTS.
               Can be list of comma separated string.
        :param str host_id: ID of :class:`taf.config.testline.testpc.TestPc`
        :param bool bts_recovery: Flag whether BTS recovery shall be executed if full commissioning fails.
               Recovery is True (enabled) by default.
        :param bool recovery_snapshot: Automatically collects snapshot before reset on eNB is performed
               due to any recovery action.
        """
        vcu_scfc = vcu_scfc or []
        vdu_scfc = vdu_scfc or []
        self._add_params_to_user_config(
            {"bts_recovery": opt_bool(bts_recovery), "recovery_snapshot": opt_bool(recovery_snapshot)}
        )
        cloud_bts_config = {
            "vcu_scfc": vcu_scfc,
            "vdu_scfc": vdu_scfc,
        }
        self._update_config(host_id, cloud_bts_config, DevicesNames.CLOUD_BTS)

    def add_enb_configuration(
        self,
        scfc: str | None = None,
        rad_params: str | list | None = None,
        vendor_params: str | list | None = None,
        host_id: str = "1",
        bts_recovery: bool = True,
        recovery_snapshot: bool = False,
        primary: bool = False,
        secondary: bool = False,
        commissioning_timeout: int | float | str = Timeouts.COMMISSIONING_TIMEOUT,
    ) -> None:
        """
        Add eNB to the configuration, so it can be started and configured with proper files.
        It sets VLAN if defined in __init__.py of the TL configuration.
        In case of full-rack configurations, `add_enb` MUST be always used for secondary eNB with `secondary=True`.

        :param str | None scfc: Name of SCFC within test directory or full path.
        :param str | list | None rad_params: R&D parameters provided either by list or comma separated or full path
               to the file which will be uploaded without any changes.
        :param str | list | None vendor_params: Vendor parameters provided either by list or comma separated.
          If there is a list of list, you can specify some constraints which will filter a list that you want to use.
          E.g. ``NRBTS.bbPoolCapacity___ABIO___FDD.maxNumDlSubcellL1Pool=1`` will only change value of
          ``maxNumDlSubcellL1Pool`` inside ``bbPoolCapacity`` if there are also ``ABIO`` and ``FDD`` on the same list.
          You can use as many constraints as you want by using ``___`` before each of them.
        :param str host_id: ID of :class:`taf.config.testline.testpc.TestPc`
        :param bool bts_recovery: Flag whether BTS recovery shall be executed if full commissioning fails.
               Recovery is True (enabled) by default.
        :param bool recovery_snapshot: Automatically collects snapshot before reset on eNB is performed
               due to any recovery action.
        :param primary: Information if this enb is primary for full-rack configuration.
        :param secondary: Information if this enb is secondary for full-rack configuration.
        :param int | float | str commissioning_timeout: Timeout for full commissioning. Can be provided either as seconds
               or timestring, e.g. '15 min', '30 min 15 sec'. Default value is 10 min.
        """
        self._add_bts(
            DevicesNames.ENB,
            bts_recovery,
            host_id,
            rad_params,
            recovery_snapshot,
            scfc,
            vendor_params,
            primary,
            secondary,
            commissioning_timeout,
        )

    def add_gnb_configuration(
        self,
        scfc: str | None = None,
        rad_params: str | list | None = None,
        vendor_params: str | list | None = None,
        host_id: str = "1",
        bts_recovery: bool = True,
        recovery_snapshot: bool = False,
        primary: bool = False,
        secondary: bool = False,
        commissioning_timeout: int | float | str = Timeouts.COMMISSIONING_TIMEOUT,
    ) -> None:
        """
        Add gNB to the configuration, so it can be started and configured with proper files.
        It sets VLAN if defined in __init__.py of the TL configuration.
        In case of full-rack configurations, `add_enb` MUST be always used for secondary eNB with `secondary=True`.

        :param str | None scfc: Name of SCFC within test directory or full path.
        :param str | list | None rad_params: R&D parameters provided either by list or comma separated or full path
               to the file which will be uploaded without any changes.
        :param str | list | None vendor_params: Vendor parameters provided either by list or comma separated.
          If there is a list of list, you can specify some constraints which will filter a list that you want to use.
          E.g. ``NRBTS.bbPoolCapacity___ABIO___FDD.maxNumDlSubcellL1Pool=1`` will only change value of
          ``maxNumDlSubcellL1Pool`` inside ``bbPoolCapacity`` if there are also ``ABIO`` and ``FDD`` on the same list.
          You can use as many constraints as you want by using ``___`` before each of them.
        :param str host_id: ID of :class:`taf.config.testline.testpc.TestPc`
        :param bool bts_recovery: Flag whether BTS recovery shall be executed if full commissioning fails.
               Recovery is True (enabled) by default.
        :param bool recovery_snapshot: Automatically collects snapshot before reset on eNB is performed
               due to any recovery action.
        :param primary: Information if this enb is primary for full-rack configuration.
        :param secondary: Information if this enb is secondary for full-rack configuration.
        :param int | float | str commissioning_timeout: Timeout for full commissioning. Can be provided either as seconds
               or timestring, e.g. '15 min', '30 min 15 sec'. Default value is 10 min.
        """
        self._add_bts(
            DevicesNames.GNB,
            bts_recovery,
            host_id,
            rad_params,
            recovery_snapshot,
            scfc,
            vendor_params,
            primary,
            secondary,
            commissioning_timeout,
        )

    def _add_bts(
        self,
        bts_type,
        bts_recovery,
        host_id,
        rad_params,
        recovery_snapshot,
        scfc,
        vendor_params,
        primary,
        secondary,
        commissioning_timeout,
    ):
        self._add_params_to_user_config(
            {
                "bts_recovery": opt_bool(bts_recovery),
                "recovery_snapshot": opt_bool(recovery_snapshot),
            }
        )
        enb_config = {
            "scfc": scfc,
            "vendor_params": vendor_params,
            "rad_params": rad_params,
            "primary": opt_bool(primary),
            "secondary": opt_bool(secondary),
            Timeouts.COMMISSIONING_TIMEOUT.name: time_to_seconds(commissioning_timeout),
        }
        self._update_config(host_id, enb_config, bts_type)

    def add_simulator(
        self,
        sim_type: str,
        config: str,
        host_id: str = "1",
        bts_id: int = 1,
        warning_lookup: bool = False,
        wtssim_alias: str | None = None,
        egate_timeout: int | str | float = Timeouts.EGATE_TIMEOUT,
        check_wts_version: bool = True,
        skip_restart: bool = False,
    ) -> None:
        """
        Add simulator to the configuration, so it can be started and configured with proper files.
        In case you are using Cloud BTS, xml file with simulator config will NOT be modified - neither VLANs nor
        build version. Please keep in mind that you need to take of tha file on your own.

        :param str sim_type: Name of simulator type. Supported models: Iphy, RTG, CUS, AirPhone
        :param str config: path to configuration file. In case of RTG/CUS if both .ini and .db are to be provided
               they need to be separated with a single comma, e.g. cus.ini,ue.db
        :param str host_id: ID of :class:`taf.config.testline.testpc.TestPc`
        :param int bts_id: ID of eNB or gNB to which simulator is connected
        :param bool warning_lookup: This flag controls if any `warning` found during simulator configuration
               should fail procedure. By default, it's set to False.
        :param str | None wtssim_alias: name of alias for WTS (edaemon and egate).
        :param int | str | float egate_timeout: user-specific timeout can be set to wait for ACTIVE state.
        :param bool check_wts_version: Flag controlling if upon activation of EPC, components versions
               should be validated. By default, it's set to True.
        :param bool skip_restart: If set to false, simulator will not be restarted. In case of CUS,
               config will not be uploaded into the device.
        """
        simulator_factory: dict[str, Callable] = {
            DevicesNames.RTG: partial(
                self._add_rtg_cus,
                warning_lookup=opt_bool(warning_lookup),
                wtssim_alias=wtssim_alias,
                egate_timeout=time_to_seconds(egate_timeout),
                check_wts_version=opt_bool(check_wts_version),
            ),
            DevicesNames.CUS: partial(
                self._add_rtg_cus,
                warning_lookup=opt_bool(warning_lookup),
                wtssim_alias=wtssim_alias,
                egate_timeout=time_to_seconds(egate_timeout),
                check_wts_version=opt_bool(check_wts_version),
            ),
            DevicesNames.IPHY: self._add_iphy,
            DevicesNames.AIRPHONE: self._add_airphone,
        }
        sim_type = convert_sim_type_to_enum(sim_type)
        add_sim_function = simulator_factory[sim_type]
        files_config = add_sim_function(config=config)
        sim_config = {
            # "type": sim_type.lower(),
            "connected_bts_id": int(bts_id),
        }
        sim_config.update(files_config)
        self._update_config(host_id, sim_config, sim_type)
        self._add_params_to_user_config({"skip_restart": opt_bool(skip_restart)})

    def _add_rtg_cus(
        self,
        warning_lookup: bool,
        config: str,
        wtssim_alias: str | None,
        egate_timeout: float,
        check_wts_version: bool,
    ) -> RtgCusConfigType:
        config = prepare_input_rtg_cus_config(config)
        self._add_params_to_user_config({"warning_lookup": warning_lookup})
        if self._is_cus_config_as_yaml(config):
            self._add_epc_config_for_cus_yaml(config["file"], wtssim_alias, egate_timeout, check_wts_version)
        return config

    @staticmethod
    def _add_iphy(config: str) -> dict[str, str | int]:
        return prepare_input_iphy_config(config)

    @staticmethod
    def _add_airphone(config: str) -> dict[str, str | int]:
        return prepare_input_airphone_config(config)

    @staticmethod
    def _is_cus_config_as_yaml(config):
        return config["api"] == SimConfigType.CUS_YAML

    def add_epc(
        self,
        config: str,
        egate_timeout: int = Timeouts.EGATE_TIMEOUT,
        wtssim_alias: str | None = None,
        check_wts_version: bool = True,
        edaemon_ports: tuple | str | int = DEFAULT_4G_EDAEMON_PORTS,
    ) -> None:
        """
        Add EPC to the configuration, so it can be started and configured with proper config file.

        :param str config: path to configuration file.
        :param int | None egate_timeout: user-specific timeout can be set to wait for ACTIVE state.
        :param str | None wtssim_alias: name of alias for WTS (edaemon and egate).
        :param bool | None check_wts_version: Flag controlling if upon activation of EPC, components versions
               should be validated. By default, it's set to True.
        :param tuple[int] | str | int edaemon_ports: Port(s) on which edaemon(s) should be started.
               Default ports are (10000, 30000).
        """
        self._add_wts(config, egate_timeout, wtssim_alias, check_wts_version, edaemon_ports, DEFAULT_EPC_PATH)

    def add_5gc(
        self,
        config: str,
        egate_timeout: int = Timeouts.EGATE_TIMEOUT,
        wtssim_alias: str | None = None,
        check_wts_version: bool = False,
        edaemon_ports: tuple | str | int = DEFAULT_5G_EDAEMON_PORTS,
    ) -> None:
        """
        Add 5GC to the configuration, so it can be started and configured with proper config file.

        :param str config: path to configuration file.
        :param int | None egate_timeout: user-specific timeout can be set to wait for ACTIVE state.
        :param str | None wtssim_alias: name of alias for WTS (edaemon and egate).
        :param bool | None check_wts_version: Flag controlling if upon activation of NRC, components versions
               should be validated. By default, it's set to False.
        :param tuple[int] | str | int edaemon_ports: Port(s) on which edaemon(s) should be started.
               Default port is 22222.
        """
        self._add_wts(config, egate_timeout, wtssim_alias, check_wts_version, edaemon_ports, DEFAULT_5GC_PATH)

    def _add_wts(
        self,
        config: str,
        egate_timeout: int,
        wtssim_alias: str | None,
        check_wts_version: bool,
        edaemon_ports: tuple | str | int,
        tool_dir: str,
    ) -> None:
        edaemon_ports = tuple(edaemon_ports) if isinstance(edaemon_ports, (list, tuple)) else (int(edaemon_ports),)
        self._add_params_to_user_config(
            {
                "egate_timeout": time_to_seconds(egate_timeout),
                "wtssim_alias": wtssim_alias,
                "check_wts_version": opt_bool(check_wts_version),
                "edaemon_ports": edaemon_ports,
                "tool_dir": tool_dir,
            }
        )
        assert Path(config).exists(), "wts config path doesn't exists."
        wts_config = {CFG_WTS.CONFIG_FP: config}
        self._config["wts"] = wts_config

    def configure_environment(
        self,
        start_mode: str = "configure",
        validate_enb: bool = True,
        validate_gnb: bool = True,
        validate_cloud_bts: bool = True,
        validate_sim: bool = True,
        rmod_detection: bool = True,
        rmod_detection_timeout: int | float | str = Timeouts.RMOD_DETECTION_TIMEOUT,
        config_removal: str = "",
        dryrun: bool = False,
    ) -> None:
        """
        Configures test environment using everything that was added before calling this method.
        Keep in mind that you can call it multiple times, but you have to `add` everything that needs to be configured
        on next iteration.

        :param str start_mode: Mode of configuration. Accepted values: [configure, validate].
               Check `validate_simulator_online` method for "validate" mode.
        :param bool validate_enb: flag to validate eNB onAir state or not.
        :param bool validate_gnb: flag to validate gNB onAir state or not.
        :param bool validate_cloud_bts: flag to validate cloud BTS onAir state or not.
        :param bool validate_sim: flag to validate simulator readiness state or not.
        :param bool rmod_detection: flag to check for RMODs after devices are up or not.
        :param int | float | str rmod_detection_timeout: Timeout for detection of RMODs.
               Can be provided either as seconds or timestring, e.g. '15 min', '30 min 15 sec'. Default value is 15 min.
        :param config_removal: Flag to handle removal of configuration files after configuration - current values:
               "" - no value, default option, always remove config via ssh
               skip - skip the step of config removal
               Possible values in next release:  - admin - remove via 3rd party library
        :param bool dryrun: if set, only config file will be created, configurator will not run.
        """
        if not self._config:
            logger.warn(f"{PACKAGE_NAME} configuration called without anything added. Nothing will happen.")
            return None
        self._CONFIGURE_CALLED = True
        self._save_additional_config_parameters(
            start_mode=start_mode,
            validate_enb=opt_bool(validate_enb),
            validate_gnb=opt_bool(validate_gnb),
            validate_cloud_bts=opt_bool(validate_cloud_bts),
            validate_sim=validate_sim,
            rmod_detection=rmod_detection,
            rmod_detection_timeout=time_to_seconds(rmod_detection_timeout),
            config_removal=config_removal,
            dryrun=dryrun,
        )
        dump_config_to_file(self._config, self._config_file)
        make_sure_directory_exists(self._output_dir)
        validate_full_rack_pairs(self._config)
        python_executable = sys.executable
        with self._output_dir.joinpath("nohup_std.out").open("w") as out_err_f:
            process = Popen(
                [
                    "nohup",
                    python_executable,
                    CONFIGURATION_MANAGER.as_posix(),
                    start_mode,
                    f"> {self._output_dir}/nohup.out",
                    "2>&1",
                    "&",
                ],
                shell=False,
                universal_newlines=True,
                stdin=out_err_f,
                stderr=out_err_f,
            )
            logger.info(f"taf.ul.ue.sim.env_setup v{get_version(PACKAGE_NAME)} started", html=True, also_console=True)
            self._finalize_configuration(process)
        self._clear_config()

    def _finalize_configuration(self, process):
        process_result = self._wait_till_configurator_ends(process)
        if process_result["status"] is False:
            self._process_configuration_failure(process, process_result["is_alive"])
        else:
            result = self._read_result()
            logger.info(f"{PACKAGE_NAME} finished. Result: {result['status']}", html=True, also_console=True)
            self._log_recoveries()
            self._finalize_with_verdict(result)

    def _finalize_with_verdict(self, result: dict) -> None:
        if result["status"] == "SUCCESS":
            return None
        elif result["status"] == "FAILURE":
            self._log_failure_status(result)
            exc_info = result["info"]
            exc_class = type(str(exc_info["type"]), (Exception,), {})
            raise exc_class(exc_info["message"])

    def _clear_config(self):
        self._CONFIGURE_CALLED = False
        self._config = {}

    @staticmethod
    def _get_output_dir() -> Path:
        output_directory = Path(get_robot_variable("OUTPUT_DIR", Path.cwd().as_posix()))
        logger.info(f"Output directory for env_setup: {output_directory}")
        return output_directory

    def _save_additional_config_parameters(self, **kwargs):
        if not self._config.get("additional_config_params"):
            self._config["additional_config_params"] = {}
        self._call_counter = next(self._CONFIGURE_CALL_COUNTER)
        self._config["additional_config_params"].update(
            {
                OUTPUT_DIRECTORY: self._output_dir.as_posix(),
                SUITE_CONFIG_DIR: self._get_config_directory_path(),
                CONFIG_CALL_COUNTER: self._call_counter,
            }
        )
        self._add_params_to_user_config(kwargs)

    def _prepare_host_config(self, host_id: str) -> dict:
        if host_id not in self._config:
            self._config[host_id] = {}
        return self._config[host_id]

    def _update_config(self, host_id: str, config: dict, dev: DevicesNames) -> None:
        host_id = str(host_id)
        host_config = self._prepare_host_config(host_id)
        if dev not in host_config:
            host_config[dev] = []
        host_config[dev].append(config)

    def _wait_till_configurator_ends(self, configurator_process: Popen) -> dict[str, bool | int]:
        result = self._get_configuration_process_result(configurator_process)
        self._copy_result_file()
        sleep(2)
        return result

    def _get_configuration_process_result(self, configurator_process: Popen) -> dict[str, bool | int]:
        start_time = time()
        is_alive = 2
        timeout = self._get_configuration_total_timeout()
        while (time() - start_time <= timeout) and is_alive:
            try:
                assert self._result_file.stat().st_size > 0
                return {"status": True, "is_alive": is_alive}
            except (OSError, AssertionError):
                sleep(1)
            if configurator_process.poll() is not None:
                is_alive -= 1
        return {"status": False, "is_alive": is_alive}

    def _get_configuration_total_timeout(self):
        timeout = (
            self._config["user_config_params"].get("rmod_detection_timeout", Timeouts.RMOD_DETECTION_TIMEOUT)
            + self._config["user_config_params"].get("egate_timeout", Timeouts.EGATE_TIMEOUT)
        ) * 2 + 30 * 60  # detections * 2 + 30 min
        return timeout

    def _process_configuration_failure(self, configurator_proc, is_alive):
        if is_alive:
            raise TimeoutError(
                "Timeout occurred on waiting for configurator result. "
                "Result unknown, check taf.ul.ue.sim.env_setup.log for more details."
            )
        self._log_error_from_configuration_process(configurator_proc)
        raise RuntimeError("configuration_manager.py ended with no result. Something gone terribly wrong")

    @staticmethod
    def _log_error_from_configuration_process(configurator_proc):
        try:
            configurator_proc_result = configurator_proc.communicate()
            logger.error(configurator_proc_result)
        except Exception as err:
            logger.error(str(err))

    def _copy_result_file(self):
        try:
            copy(self._result_file, self._output_dir)
        except FileNotFoundError:
            logger.error(f"Cannot copy result file to output directory - {self._result_file} does not exist.")

    def _read_result(self) -> dict:
        return load_file(self._result_file)

    @staticmethod
    def _log_failure_status(result: dict):
        add_info = result["info"]
        logger.error("{} - {}".format(str(add_info["type"]), str(add_info["message"])))
        logger.error(str(add_info["tb"]), html=True)

    def _log_recoveries(self):
        log_file = self._output_dir.joinpath(f"{RECOVERY_LOG_NAME}_{self._call_counter}.log")
        if not log_file.exists() or log_file.stat().st_size == 0:
            return
        with log_file.open("r") as log_file_handler:
            logger.warn("Recoveries during configuration:")
            for line in log_file_handler:
                logger.warn(line.strip("\n"), html=True)

    @staticmethod
    def _get_config_directory_path() -> str:
        """
        Gets config directory as a Robot variable ${SUITE_SOURCE}
        :return: config dirpath as a string
        """
        suite_source_name = get_robot_variable("SUITE_SOURCE", "")
        suite_path = Path(suite_source_name).parent if suite_source_name else Path.cwd()
        return suite_path.joinpath("config").as_posix()

    def _add_params_to_user_config(self, _dict):
        if not self._config.get("user_config_params"):
            self._config["user_config_params"] = {}
        self._config["user_config_params"].update(_dict)

    def _add_epc_config_for_cus_yaml(
        self, config: str, wtssim_alias: str | None, egate_timeout: float, check_wts_version: bool
    ) -> None:
        self._add_params_to_user_config(
            {
                "wtssim_alias": wtssim_alias,
                "egate_timeout": egate_timeout,
                "check_wts_version": check_wts_version,
                "edaemon_ports": DEFAULT_4G_EDAEMON_PORTS,
                "cus_yaml": config,
            }
        )
